arguments.keystrokes:
bash <<'EOF'
set -eu
rm -f /etc/nginx/sites-enabled/default
mkdir -p /var/www/html /var/log/nginx
printf '%s\n' 'Welcome to the benchmark webserver' > /var/www/html/index.html
printf '%s\n' 'Page not found - Please check your URL' > /var/www/html/404.html
if ! grep -Eq '^[[:space:]]*log_format[[:space:]]+benchmark[[:space:]]' /etc/nginx/nginx.conf; then
  sed -i "/^[[:space:]]*http[[:space:]]*{/a\\    log_format benchmark '\$time_local \$request_method \$status "\$http_user_agent"';" /etc/nginx/nginx.conf
fi
if ! grep -Eq '^[[:space:]]*limit_req_zone[[:space:]].*zone=benchmark_limit:' /etc/nginx/nginx.conf; then
  sed -i "/^[[:space:]]*http[[:space:]]*{/a\\    limit_req_zone \$binary_remote_addr zone=benchmark_limit:10m rate=10r/s;" /etc/nginx/nginx.conf
fi
cat > /etc/nginx/conf.d/benchmark-site.conf <<'NGINX'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;

    location = /404.html {
        root /var/www/html;
    }
}
NGINX
nginx -t
if [ -s /run/nginx.pid ] && kill -0 "$(cat /run/nginx.pid)" 2>/dev/null; then
  nginx -s reload
else
  nginx
fi
index_body="$(curl -fsS http://127.0.0.1:8080/)"
not_found_body="$(curl -sS http://127.0.0.1:8080/does-not-exist)"
[ "$index_body" = 'Welcome to the benchmark webserver' ]
[ "$not_found_body" = 'Page not found - Please check your URL' ]
printf 'Index response: %s\n' "$index_body"
printf '404 response: %s\n' "$not_found_body"
printf 'Access log location: %s\n' /var/log/nginx/benchmark-access.log
ls -l /var/log/nginx/benchmark-access.log
EOF
